; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0

; ---- variables ----
readKey__ret:   dw      0        ; u16
strLen__at:     dw      0        ; u16
strLen__ret:    dw      0        ; u16
elCount:        dw      0        ; u16
openDepth:      dw      0        ; u16
childBufLen:    dw      0        ; u16
childListLen:   dw      0        ; u16
setSize__i:     dw      0        ; u16
setSize__xAxis: db      0        ; bool
setSize__v:     dw      0        ; u16
setOverflow__i: dw      0        ; u16
setOverflow__xAxis: db      0        ; bool
cfg__isCol:     db      0        ; bool
cfg__insetL:    db      0        ; u8
cfg__insetR:    db      0        ; u8
cfg__insetT:    db      0        ; u8
cfg__insetB:    db      0        ; u8
cfg__gap:       db      0        ; u8
cfg__alignMain: db      0        ; u8
cfg__alignCross: db      0        ; u8
cfg__wGrow:     db      0        ; bool
cfg__wMin:      dw      0        ; u16
cfg__wMax:      dw      0        ; u16
